<script setup lang="ts">
import {computed,ref,watch,onMounted} from 'vue';import {ElMessage,ElMessageBox} from 'element-plus';import {Plus,Search,User,Document,Calendar} from '@element-plus/icons-vue';import {useAuthApi,isStaleAuthError,dateTime,taskLabel} from '../api';
import ScheduleDialog from './ScheduleDialog.vue';import WebAccountPanel from './WebAccountPanel.vue';
const api=useAuthApi();
const props=defineProps<{refreshKey:number}>();const emit=defineEmits(['changed','open-review']);const items=ref<any[]>([]);const query=ref('');const selected=ref<any>(null);const loading=ref(false);const busy=ref(false);
const createOpen=ref(false);const recordOpen=ref(false);const scheduleOpen=ref(false);
const form=ref({name:'',birthDate:'',sex:'unspecified',phone:''});const medical=ref<any>({});
const filtered=computed(()=>items.value.filter(p=>p.name.includes(query.value)||(p.phone||'').includes(query.value)));
let selectionRequest=0;
let refreshRequest=0;
async function refresh(){const request=++refreshRequest;loading.value=true;try{const result=await api('/clinician/patients');if(request!==refreshRequest)return;items.value=result.items;if(selected.value)await select({id:selected.value.patient.id});}catch(e){if(request===refreshRequest&&!isStaleAuthError(e))ElMessage.error((e as Error).message);}finally{if(request===refreshRequest)loading.value=false;}}
async function select(p:any){const request=++selectionRequest;try{const result=await api('/clinician/patients/'+p.id);if(request===selectionRequest)selected.value=result;}catch(e){if(request===selectionRequest&&!isStaleAuthError(e))ElMessage.error((e as Error).message);}}
function newPatient(){form.value={name:'',birthDate:'',sex:'unspecified',phone:''};createOpen.value=true;}
async function create(){busy.value=true;try{const p=await api('/clinician/patients','POST',form.value);createOpen.value=false;await refresh();await select(p);emit('changed');ElMessage.success('档案已建立，可在详情中开通患者网页账号');}catch(e){if(!isStaleAuthError(e))ElMessage.error((e as Error).message);}finally{busy.value=false;}}
function editRecord(){medical.value={diagnosis:'',history:'',dischargeSummary:'',carePlan:'',medications:'',...selected.value.patient.medicalRecord};recordOpen.value=true;}
async function saveMedical(){busy.value=true;try{await api(`/clinician/patients/${selected.value.patient.id}/medical-record`,'PUT',{expectedVersion:selected.value.patient.version,record:medical.value});recordOpen.value=false;await select(selected.value.patient);ElMessage.success('病历已保存，患者端可查看');}catch(e){if(!isStaleAuthError(e))ElMessage.error((e as Error).message);}finally{busy.value=false;}}
async function resolveCorrection(c:any){try{const answer=await ElMessageBox.prompt('请说明核对情况，以及已做的更正或无需更改的原因。','处理资料更正申请',{inputType:'textarea',inputValidator:(v:string)=>Boolean(v.trim())||'请填写处理说明'});await api(`/clinician/patients/${selected.value.patient.id}/corrections/${c.id}/resolve`,'POST',{resolution:answer.value.trim()});await select(selected.value.patient);emit('changed');}catch(e){if(!isStaleAuthError(e))ElMessage.error((e as Error).message);}}
watch(()=>props.refreshKey,refresh);onMounted(refresh);
</script>
<template><section class="page-heading"><div><span class="eyebrow">PATIENTS</span><h1>患者管理</h1><p>从建档到随访，持续了解每一位患者。</p></div><el-button type="primary" size="large" :icon="Plus" @click="newPatient">新建患者</el-button></section><div class="patients-grid"><section class="panel patient-list"><div class="panel-toolbar"><h3>我的患者 <span class="count">{{items.length}}</span></h3><el-input v-model="query" :prefix-icon="Search" placeholder="搜索姓名或联系方式" clearable class="search-input"/></div><el-table :data="filtered" v-loading="loading" @row-click="select" class="clickable-table" empty-text="还没有患者，请先新建档案"><el-table-column label="患者" min-width="145"><template #default="{row}"><div class="patient-cell"><span class="avatar">{{row.name.slice(-1)}}</span><div><strong>{{row.name}}</strong><small>{{row.birthDate}} · {{row.sex==='male'?'男':row.sex==='female'?'女':'未填写性别'}}</small></div></div></template></el-table-column><el-table-column label="联系方式" prop="phone" min-width="124"><template #default="{row}">{{row.phone||'尚未填写'}}</template></el-table-column></el-table><div class="table-footer">选择患者，查看档案和随访安排</div></section><aside class="panel patient-detail" v-if="selected"><div class="detail-profile"><span class="avatar big">{{selected.patient.name.slice(-1)}}</span><div><h2>{{selected.patient.name}}</h2><p>{{selected.patient.birthDate}} 出生 <span class="status" :class="selected.bound?'green':'gray'">{{selected.bound?'已关联患者账户':'尚未开通账户'}}</span></p></div></div><div class="detail-actions"><el-button type="primary" @click="scheduleOpen=true" :icon="Calendar">安排随访</el-button><el-button @click="editRecord" :icon="Document">维护病历</el-button></div><WebAccountPanel :key="selected.patient.id" :patient-id="selected.patient.id" :patient-name="selected.patient.name" @changed="emit('changed')"/><div class="detail-section"><h3>基本资料</h3><dl class="key-values"><dt>联系电话</dt><dd>{{selected.patient.phone||'尚未填写'}}</dd><dt>紧急联系人</dt><dd>{{selected.patient.emergencyContact||'尚未填写'}} {{selected.patient.emergencyPhone}}</dd><dt>个人补充</dt><dd>{{selected.patient.personalNotes||'暂无'}}</dd></dl></div><div class="detail-section"><h3>病历摘要 <small>第 {{selected.patient.version}} 版</small></h3><p class="preserve">{{selected.patient.medicalRecord.diagnosis||'诊断记录尚未填写'}}</p><p class="muted preserve" v-if="selected.patient.medicalRecord.carePlan">{{selected.patient.medicalRecord.carePlan}}</p></div><div class="detail-section"><h3>随访安排</h3><div v-for="task in selected.tasks.slice(0,4)" :key="task.id" class="timeline-item"><span class="timeline-dot"></span><div><strong>{{task.title}}</strong><small>{{dateTime(task.scheduled_at)}} · {{taskLabel(task.status)}}<em v-if="task.overdue"> · 已逾期</em></small></div></div><p v-if="!selected.tasks.length" class="muted">还没有安排随访。</p></div><div class="detail-section" v-if="selected.corrections.length"><h3>资料更正申请</h3><div class="notice-card" v-for="c in selected.corrections" :key="c.id"><p>{{c.content}}</p><el-button v-if="c.status==='pending'" size="small" @click="resolveCorrection(c)">已核对并处理</el-button><small v-else class="muted">已处理：{{c.resolution}}</small></div></div><div class="detail-section" v-if="selected.sessions.length"><h3>最近随访</h3><div v-for="s in selected.sessions.slice(0,4)" :key="s.id" class="record-link"><span>{{dateTime(s.started_at)}} · {{s.review_status==='reviewed'?'已审核':'待处理'}}</span><el-button text type="primary" @click="emit('open-review',s.id)">查看记录 →</el-button></div></div></aside><aside v-else class="panel detail-empty"><el-icon :size="42"><User/></el-icon><h3>查看患者档案</h3><p>从左侧选择一位患者<br>在这里维护资料、安排随访。</p></aside></div>
<el-dialog v-model="createOpen" title="新建患者档案" width="500px"><el-form label-position="top" @submit.prevent="create"><el-form-item label="患者姓名" for="patient-name"><el-input id="patient-name" v-model="form.name" maxlength="80" placeholder="请输入姓名"/></el-form-item><div class="form-row"><el-form-item label="出生日期" for="patient-birth"><input id="patient-birth" type="date" v-model="form.birthDate" class="native-input"/></el-form-item><el-form-item label="性别"><el-select v-model="form.sex"><el-option label="暂未填写" value="unspecified"/><el-option label="男" value="male"/><el-option label="女" value="female"/></el-select></el-form-item></div><el-form-item label="联系电话" for="patient-phone"><el-input id="patient-phone" v-model="form.phone" placeholder="可稍后补充" maxlength="32"/></el-form-item><p class="muted">建档后在患者详情中开通网页账号，患者通过独立的患者网站登录。</p></el-form><template #footer><el-button @click="createOpen=false">取消</el-button><el-button type="primary" @click="create" :loading="busy">保存并建档</el-button></template></el-dialog>
<el-dialog v-model="recordOpen" title="维护病历" width="680px"><el-form label-position="top"><el-form-item v-for="field in [{key:'diagnosis',label:'诊断记录'},{key:'history',label:'既往病史'},{key:'dischargeSummary',label:'出院摘要'},{key:'carePlan',label:'随访与照护计划'},{key:'medications',label:'用药记录'}]" :key="field.key" :label="field.label" :for="'medical-'+field.key"><el-input :id="'medical-'+field.key" type="textarea" :rows="3" v-model="medical[field.key]" maxlength="6000"/></el-form-item></el-form><template #footer><el-button @click="recordOpen=false">取消</el-button><el-button type="primary" @click="saveMedical" :loading="busy">保存病历</el-button></template></el-dialog>
<ScheduleDialog v-model:open="scheduleOpen" :patient-id="selected?.patient.id||''" @saved="refresh();emit('changed')"/>
</template>
